package dev.pocketrun.agent.opencode

import dev.pocketrun.core.Workspace
import java.io.File

/**
 * opencode Agent Skills: `SKILL.md` files with YAML frontmatter, discovered
 * from the project (`.opencode/skills/<name>/SKILL.md`, plus `.claude/` and
 * `.agents/` compatibility locations) and from the global config directory
 * (mapped to `<workspace>/opencode/skills/` on the device).
 *
 * Skills are advertised in the `skill` tool description as
 * `<available_skills>` XML and loaded on demand by the model.
 */
class Skills(private val workspace: Workspace) {

    data class Skill(val name: String, val description: String, val file: File, val global: Boolean) {
        val content: String by lazy { file.readText(Charsets.UTF_8) }
    }

    /** Global `~/.config/opencode/skills` analog. */
    val globalDir: File get() = File(workspace.root, "opencode/skills")

    /** Project skill locations, in opencode's search order. */
    private fun projectDirs(projectDir: File): List<File> = listOf(
        File(projectDir, ".opencode/skills"),
        File(projectDir, ".claude/skills"),
        File(projectDir, ".agents/skills"),
    )

    /**
     * All valid skills for [projectDir]: global first, then project ones.
     * Later entries with the same name are skipped (first wins, like opencode's
     * precedence rules in reverse order of discovery — global is the fallback).
     */
    fun discover(projectDir: File?): List<Skill> {
        val found = mutableListOf<Skill>()
        if (projectDir != null) {
            for (dir in projectDirs(projectDir)) found += scan(dir, global = false)
        }
        found += scan(globalDir, global = true)
        val seen = mutableSetOf<String>()
        return found.filter { seen.add(it.name) }
    }

    private fun scan(dir: File, global: Boolean): List<Skill> {
        if (!dir.isDirectory) return emptyList()
        return dir.listFiles { f -> f.isDirectory }
            .orEmpty()
            .mapNotNull { folder ->
                val file = File(folder, "SKILL.md")
                if (!file.isFile) return@mapNotNull null
                val front = parseFrontmatter(file.readText(Charsets.UTF_8))
                val name = front["name"]?.trim().orEmpty()
                val description = front["description"]?.trim().orEmpty()
                if (!nameMatches(folder.name) || name.isEmpty() || description.isEmpty()) null
                else Skill(name, description, file, global)
            }
            .sortedBy { it.name }
    }

    fun load(name: String, projectDir: File?): Skill? =
        discover(projectDir).firstOrNull { it.name == name }

    /** The `<available_skills>` block embedded in the tool description. */
    fun availableSkillsXml(projectDir: File?): String {
        val skills = discover(projectDir)
        if (skills.isEmpty()) return ""
        return buildString {
            append("<available_skills>\n")
            for (s in skills) {
                append("  <skill>\n")
                append("    <name>${s.name}</name>\n")
                append("    <description>${escape(s.description)}</description>\n")
                append("  </skill>\n")
            }
            append("</available_skills>\n")
        }
    }

    companion object {
        private val NAME_REGEX = Regex("^[a-z0-9]+(-[a-z0-9]+)*$")

        fun nameMatches(name: String): Boolean =
            name.length in 1..64 && NAME_REGEX.matches(name)

        /** Minimal YAML frontmatter parser: flat `key: value` lines. */
        fun parseFrontmatter(text: String): Map<String, String> {
            val out = mutableMapOf<String, String>()
            val lines = text.lines()
            if (lines.firstOrNull()?.trim() != "---") return out
            var i = 1
            while (i < lines.size && lines[i].trim() != "---") {
                val line = lines[i]
                val idx = line.indexOf(':')
                if (idx > 0) {
                    val key = line.substring(0, idx).trim()
                    var value = line.substring(idx + 1).trim()
                    // continuation lines (indented, e.g. metadata maps) are ignored
                    if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) {
                        value = value.substring(1, value.length - 1)
                    }
                    if (key.isNotEmpty() && !out.containsKey(key)) out[key] = value
                }
                i++
            }
            return out
        }

        private fun escape(s: String): String =
            s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    }
}

package dev.pocketrun.agent.opencode

import dev.pocketrun.core.Workspace
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.util.UUID

/**
 * opencode-style sessions: every conversation is stored locally under
 * `<workspace>/opencode-data/sessions/<id>.json` with its title, project,
 * parent (forks), the OpenAI-format message history and the todo list —
 * so a session can be resumed, forked, renamed, exported or deleted.
 */
class Sessions(private val workspace: Workspace) {

    data class Todo(val id: String, val content: String, val status: String) {
        val isActive: Boolean get() = status == "in_progress"
        val isDone: Boolean get() = status == "completed"
    }

    data class SessionInfo(
        val id: String,
        var title: String,
        val project: String?,
        val parentID: String?,
        val createdAt: Long,
        var updatedAt: Long,
        var model: String?,
    )

    data class Session(
        val info: SessionInfo,
        var messages: JSONArray,
        var todos: List<Todo>,
    )

    private val dir: File get() = File(workspace.root, "opencode-data/sessions").apply { mkdirs() }

    fun create(project: String?, title: String? = null, parentID: String? = null, model: String? = null): Session {
        val now = System.currentTimeMillis()
        val info = SessionInfo(
            id = UUID.randomUUID().toString().replace("-", "").take(20),
            title = title?.takeIf { it.isNotBlank() } ?: "Новая сессия",
            project = project,
            parentID = parentID,
            createdAt = now,
            updatedAt = now,
            model = model,
        )
        val session = Session(info, JSONArray(), emptyList())
        save(session)
        return session
    }

    fun list(): List<SessionInfo> =
        dir.listFiles { f -> f.isFile && f.name.endsWith(".json") }
            .orEmpty()
            .mapNotNull { f -> runCatching { readInfo(f) }.getOrNull() }
            .sortedByDescending { it.updatedAt }

    fun load(id: String): Session? {
        val f = File(dir, "$id.json")
        if (!f.isFile) return null
        return try {
            val json = JSONObject(f.readText(Charsets.UTF_8))
            Session(
                info = SessionInfo(
                    id = json.getString("id"),
                    title = json.optString("title", "Сессия"),
                    project = json.optString("project").takeIf { it.isNotEmpty() && it != "null" },
                    parentID = json.optString("parentID").takeIf { it.isNotEmpty() && it != "null" },
                    createdAt = json.optLong("createdAt"),
                    updatedAt = json.optLong("updatedAt"),
                    model = json.optString("model").takeIf { it.isNotEmpty() && it != "null" },
                ),
                messages = json.optJSONArray("messages") ?: JSONArray(),
                todos = parseTodos(json.optJSONArray("todos")),
            )
        } catch (t: Throwable) {
            null
        }
    }

    fun save(session: Session) {
        session.info.updatedAt = System.currentTimeMillis()
        val todos = JSONArray().apply {
            session.todos.forEach { t ->
                put(JSONObject().put("id", t.id).put("content", t.content).put("status", t.status))
            }
        }
        val json = JSONObject()
            .put("id", session.info.id)
            .put("title", session.info.title)
            .put("project", session.info.project ?: JSONObject.NULL)
            .put("parentID", session.info.parentID ?: JSONObject.NULL)
            .put("createdAt", session.info.createdAt)
            .put("updatedAt", session.info.updatedAt)
            .put("model", session.info.model ?: JSONObject.NULL)
            .put("messages", session.messages)
            .put("todos", todos)
        File(dir, "${session.info.id}.json").writeText(json.toString(), Charsets.UTF_8)
    }

    fun delete(id: String): Boolean = File(dir, "$id.json").delete()

    fun rename(id: String, title: String): Boolean {
        val s = load(id) ?: return false
        s.info.title = title.trim().take(80).ifEmpty { s.info.title }
        save(s)
        return true
    }

    /** Fork: a copy with a new id, parent set, same history. */
    fun fork(id: String): Session? {
        val s = load(id) ?: return null
        val child = create(
            project = s.info.project,
            title = s.info.title + " (форк)",
            parentID = s.info.id,
            model = s.info.model,
        )
        child.messages = JSONArray(s.messages.toString())
        child.todos = s.todos
        save(child)
        return child
    }

    /** Most recently updated session for a project (the `--continue` analog). */
    fun latest(project: String?): Session? =
        list().firstOrNull { it.project == project }?.let { load(it.id) }

    /** Export a session as readable JSON (the `opencode export` analog). */
    fun export(id: String): String? {
        val s = load(id) ?: return null
        val f = File(workspace.root, "opencode-data/exports").apply { mkdirs() }
        val name = "session-${s.info.id}.json"
        f.resolve(name).writeText(pretty(s), Charsets.UTF_8)
        return f.resolve(name).absolutePath
    }

    fun pretty(session: Session): String {
        val json = JSONObject()
            .put("id", session.info.id)
            .put("title", session.info.title)
            .put("project", session.info.project ?: JSONObject.NULL)
            .put("parent", session.info.parentID ?: JSONObject.NULL)
            .put("created", session.info.createdAt)
            .put("updated", session.info.updatedAt)
            .put("todos", JSONArray().apply { session.todos.forEach { put(it.content + " [" + it.status + "]") } })
            .put("messages", session.messages)
        return json.toString(2)
    }

    private fun readInfo(f: File): SessionInfo? {
        val json = JSONObject(f.readText(Charsets.UTF_8))
        if (!json.has("id")) return null
        return SessionInfo(
            id = json.getString("id"),
            title = json.optString("title", "Сессия"),
            project = json.optString("project").takeIf { it.isNotEmpty() && it != "null" },
            parentID = json.optString("parentID").takeIf { it.isNotEmpty() && it != "null" },
            createdAt = json.optLong("createdAt"),
            updatedAt = json.optLong("updatedAt"),
            model = json.optString("model").takeIf { it.isNotEmpty() && it != "null" },
        )
    }

    private fun parseTodos(arr: JSONArray?): List<Todo> {
        if (arr == null) return emptyList()
        return (0 until arr.length()).mapNotNull { i ->
            val o = arr.optJSONObject(i) ?: return@mapNotNull null
            Todo(
                id = o.optString("id").ifEmpty { "t$i" },
                content = o.optString("content"),
                status = o.optString("status", "pending"),
            )
        }
    }
}

package dev.pocketrun.agent.opencode

import dev.pocketrun.core.Workspace
import java.io.File
import java.net.HttpURLConnection
import java.net.URL

/**
 * opencode instructions: `AGENTS.md` (project + global) with `CLAUDE.md`
 * fallbacks, plus the `instructions` array from an opencode-style config
 * (`<workspace>/opencode/opencode.json` stands in for
 * `~/.config/opencode/opencode.json`). Remote instruction URLs are fetched
 * with a 5 second timeout, exactly like opencode.
 */
class Instructions(private val workspace: Workspace) {

    /** Global `~/.config/opencode` analog. */
    val globalDir: File get() = File(workspace.root, "opencode")

    data class Result(val text: String, val sources: List<String>)

    /**
     * Collects instructions for [projectDir]: project AGENTS.md (or CLAUDE.md),
     * walking up to the workspace root; then the global one; then every entry
     * of the config `instructions` list (local paths relative to the project
     * or the workspace, and http(s) URLs).
     */
    fun collect(projectDir: File?): Result {
        val parts = mutableListOf<Pair<String, String>>() // source → text

        // 1. project rules, nearest first (AGENTS.md wins over CLAUDE.md per directory)
        var dir = projectDir
        val chain = mutableListOf<File>()
        while (dir != null && dir.startsWith(workspace.root) && chain.size < 8) {
            chain += dir
            dir = dir.parentFile
        }
        for (d in chain.reversed()) {
            val f = ruleFile(d) ?: continue
            val text = f.readText(Charsets.UTF_8).trim()
            if (text.isNotEmpty()) parts += workspace.relativeTo(f) to text
        }

        // 2. global rules
        val global = ruleFile(globalDir)?.readText(Charsets.UTF_8)?.trim()
        if (!global.isNullOrEmpty()) parts += workspace.relativeTo(ruleFile(globalDir)!!) to global

        // 3. instructions from config
        for (entry in configInstructions()) {
            if (entry.startsWith("http://") || entry.startsWith("https://")) {
                fetchRemote(entry)?.let { parts += entry to it }
            } else {
                val f = resolveInstructionPath(entry, projectDir) ?: continue
                if (f.isFile) {
                    val text = f.readText(Charsets.UTF_8).trim()
                    if (text.isNotEmpty()) parts += workspace.relativeTo(f) to text
                }
            }
        }

        if (parts.isEmpty()) return Result("", emptyList())
        val text = parts.joinToString("\n\n") { "# ${it.first}\n\n${it.second}" }
        return Result(text, parts.map { it.first })
    }

    /** AGENTS.md, or CLAUDE.md when AGENTS.md is absent (Claude Code compat). */
    private fun ruleFile(dir: File): File? {
        val agents = File(dir, "AGENTS.md")
        if (agents.isFile) return agents
        val claude = File(dir, "CLAUDE.md")
        if (claude.isFile) return claude
        return null
    }

    /** The `instructions` array of `<workspace>/opencode/opencode.json`. */
    internal fun configInstructions(): List<String> {
        val config = File(globalDir, "opencode.json")
        if (!config.isFile) return emptyList()
        return try {
            val json = org.json.JSONObject(config.readText(Charsets.UTF_8))
            val arr = json.optJSONArray("instructions") ?: return emptyList()
            (0 until arr.length()).mapNotNull { arr.optString(it, "").trim().takeIf { it.isNotEmpty() } }
        } catch (t: Throwable) {
            emptyList()
        }
    }

    /** Supports glob-ish entries (a directory plus `*.md`) via a simple scan. */
    private fun resolveInstructionPath(entry: String, projectDir: File?): File? {
        if (entry.endsWith("/*") || entry.endsWith("/*.md")) {
            val parent = entry.removeSuffix("*").removeSuffix("/")
            val base = workspace.resolve(parent, projectDir ?: workspace.root) ?: return null
            if (!base.isDirectory) return null
            val files = base.listFiles { f -> f.isFile && f.name.endsWith(".md") } ?: return null
            // combined into one pseudo-file: return the first; others handled by caller loop
            // — simpler: create a synthetic marker by concatenating at collect() level
            // For now single-file entries cover the common case; glob entries use the first match.
            return files.sortedBy { it.name }.firstOrNull()
        }
        return workspace.resolve(entry, projectDir ?: workspace.root)
    }

    private fun fetchRemote(url: String): String? = try {
        val conn = URL(url).openConnection() as HttpURLConnection
        conn.connectTimeout = 5_000
        conn.readTimeout = 5_000
        val status = conn.responseCode
        if (status !in 200..299) null
        else conn.inputStream.bufferedReader(Charsets.UTF_8).use { it.readText().take(48 * 1024).trim().ifEmpty { null } }
    } catch (t: Throwable) {
        null
    }
}

package dev.pocketrun.agent

import org.json.JSONArray
import org.json.JSONObject
import java.io.IOException
import java.net.HttpURLConnection
import java.net.SocketTimeoutException
import java.net.URL
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicLong

/**
 * A thin OpenAI-compatible chat-completions client: POST JSON, read JSON, turn
 * the response into [Response] (text plus any tool calls).
 *
 * Three things matter for a mobile agent loop and are implemented here:
 *
 * * **Streaming.** The request asks for `stream: true` and the answer is read
 *   as SSE, so a generation that takes many minutes keeps the connection busy
 *   (idle connections get killed by gateways and mobile networks), the ⏹ button
 *   is honoured between chunks, and the UI can show what is being written. A
 *   server that answers with a plain JSON body instead is handled transparently.
 * * **Retries.** Timeouts, resets, 429 and 5xx are retried with a backoff;
 *   everything else (bad key, unknown model) fails immediately.
 * * **Long deadlines.** A model that thinks for a long time must not lose the
 *   turn: the read timeout is 15 minutes, and a watchdog aborts a connection
 *   that goes silent for much longer than that.
 */
class LlmClient(private val config: AgentSettings.Config) {

    data class ToolCall(val id: String, val name: String, val arguments: String)
    data class Response(val content: String?, val toolCalls: List<ToolCall>)

    class LlmException(message: String) : Exception(message)

    /** The server answered, but not in a form we can use — worth one plain retry. */
    private class UnusableAnswer(val detail: String) : Exception(detail)

    /** A non-2xx answer, kept structured so retries can look at the status. */
    private class HttpFailure(val status: Int, val body: String) : Exception("HTTP $status")

    companion object {
        const val CONNECT_TIMEOUT_MS = 30_000

        /** 15 minutes — a long generation must not lose the turn. */
        const val READ_TIMEOUT_MS = 900_000

        /** No bytes for this long (and none at all since the request) = dead connection. */
        const val FIRST_TOKEN_TIMEOUT_MS = 240_000

        /** A stream that goes quiet for this long after the first token is dead too. */
        const val STALL_TIMEOUT_MS = 300_000

        const val MAX_ATTEMPTS = 3
        const val RETRY_BACKOFF_MS = 3_000L
        const val CANCELLED = "остановлено пользователем"

        private const val SSE_DATA = "data:"
        private const val SSE_DONE = "[DONE]"

        /**
         * Fetches the model list of an OpenAI-compatible server:
         * GET {baseUrl}/models, parse data[].id. Used by the model settings UI
         * (e.g. the OpenCode Zen catalog at https://opencode.ai/zen/v1).
         */
        fun models(baseUrl: String, apiKey: String): List<String> {
            val url = baseUrl.trim().trimEnd('/') + "/models"
            val conn = (URL(url).openConnection() as HttpURLConnection).apply {
                requestMethod = "GET"
                connectTimeout = 20_000
                readTimeout = 60_000
                setRequestProperty("Accept", "application/json")
                if (apiKey.isNotBlank()) setRequestProperty("Authorization", "Bearer $apiKey")
            }
            try {
                val status = conn.responseCode
                val text = (if (status in 200..299) conn.inputStream else conn.errorStream)
                    ?.bufferedReader(Charsets.UTF_8)?.use { it.readText() } ?: ""
                if (status !in 200..299) {
                    throw LlmException("HTTP $status от $url: ${text.take(300)}")
                }
                val data = JSONObject(text).optJSONArray("data") ?: return emptyList()
                val ids = mutableListOf<String>()
                for (i in 0 until data.length()) {
                    val id = data.optJSONObject(i)?.optString("id").orEmpty()
                    if (id.isNotEmpty()) ids += id
                }
                return ids.sortedWith(compareBy<String> { it.lowercase() })
            } finally {
                conn.disconnect()
            }
        }

        /**
         * Accumulates an OpenAI-style SSE stream: text deltas plus tool calls
         * whose name and arguments arrive in pieces. Kept separate from the
         * socket code so it can be tested without a server.
         */
        internal class Stream(
            private val onDelta: ((String) -> Unit)? = null,
        ) {
            private val text = StringBuilder()
            private val reasoning = StringBuilder()
            private val calls = LinkedHashMap<Int, Call>()

            private class Call {
                var id: String = ""
                var name: String = ""
                val arguments = StringBuilder()
            }

            /** Feeds one `data:` payload; malformed chunks are ignored. */
            fun feed(payload: String) {
                val json = try {
                    JSONObject(payload)
                } catch (t: Throwable) {
                    return
                }
                json.optJSONObject("error")?.let { err ->
                    val msg = err.optString("message").ifEmpty { payload.take(200) }
                    throw LlmException("сервер модели вернул ошибку: $msg")
                }
                val choice = json.optJSONArray("choices")?.optJSONObject(0) ?: return
                // `delta` for streams, `message` for servers that stream nothing.
                val delta = choice.optJSONObject("delta") ?: choice.optJSONObject("message") ?: return
                delta.optString("content").takeIf { it.isNotEmpty() }?.let {
                    text.append(it)
                    onDelta?.invoke(it)
                }
                // Reasoning models stream their thinking separately; keep it so a
                // blank `content` still produces something useful.
                delta.optString("reasoning_content").takeIf { it.isNotEmpty() }?.let { reasoning.append(it) }
                val arr = delta.optJSONArray("tool_calls") ?: return
                for (i in 0 until arr.length()) {
                    val chunk = arr.optJSONObject(i) ?: continue
                    val slot = calls.getOrPut(chunk.optInt("index", i)) { Call() }
                    chunk.optString("id").takeIf { it.isNotEmpty() }?.let { slot.id = it }
                    val fn = chunk.optJSONObject("function") ?: continue
                    fn.optString("name").takeIf { it.isNotEmpty() }?.let {
                        slot.name = if (slot.name.isEmpty()) it else slot.name + it
                    }
                    fn.optString("arguments").takeIf { it.isNotEmpty() }?.let { slot.arguments.append(it) }
                }
            }

            fun isEmpty(): Boolean = text.isBlank() && reasoning.isBlank() && calls.isEmpty()

            /**
             * The finished answer. A well-formed but empty stream yields an
             * empty [Response] on purpose: the agent nudges the model and spends
             * one round, which beats three retries of a request that will not
             * change. Only a structurally broken answer is an error.
             */
            fun result(): Response {
                val toolCalls = calls.entries.sortedBy { it.key }.map { (i, c) ->
                    ToolCall(
                        id = c.id.ifEmpty { "call_$i" },
                        name = c.name,
                        arguments = c.arguments.toString().ifBlank { "{}" },
                    )
                }.filter { it.name.isNotEmpty() }
                val content = text.toString().ifBlank { reasoning.toString() }.ifBlank { null }
                return Response(content, toolCalls)
            }
        }

        /** Turns a streamed or plain assistant message into [Response]. */
        internal fun parseMessage(message: JSONObject): Response {
            val content = if (message.isNull("content")) {
                null
            } else {
                message.optString("content").takeIf { it.isNotEmpty() }
            }
            val calls = mutableListOf<ToolCall>()
            val arr = message.optJSONArray("tool_calls")
            if (arr != null) {
                for (i in 0 until arr.length()) {
                    val call = arr.getJSONObject(i)
                    val fn = call.optJSONObject("function") ?: continue
                    val name = fn.optString("name")
                    if (name.isEmpty()) continue
                    calls += ToolCall(
                        id = call.optString("id").ifEmpty { "call_$i" },
                        name = name,
                        arguments = fn.optString("arguments", "{}").ifEmpty { "{}" },
                    )
                }
            }
            return Response(content, calls)
        }

        /** A user-readable, actionable description of a failed request. */
        internal fun describe(t: Throwable): String = when (t) {
            is LlmException -> t.message ?: "ошибка модели"
            is HttpFailure -> {
                val hint = when (t.status) {
                    401 -> " — ключ отвергнут сервером"
                    403 -> " — доступ запрещён (у Zen нужен бесплатный ключ с opencode.ai/auth)"
                    404 -> " — нет такого endpoint или модели"
                    413 -> " — запрос слишком велик (история разрослась)"
                    429 -> " — лимит запросов, попробуйте позже"
                    in 500..599 -> " — сервер модели перегружен"
                    else -> ""
                }
                "HTTP ${t.status}$hint: ${t.body.take(300)}"
            }
            is SocketTimeoutException ->
                "модель не ответила за ${READ_TIMEOUT_MS / 60_000} мин — попробуйте другую модель или упростите запрос"
            is IOException -> t.message ?: "сетевая ошибка: ${t.javaClass.simpleName}"
            else -> t.message ?: t.javaClass.simpleName
        }

        internal fun isRetryable(t: Throwable): Boolean = when (t) {
            is SocketTimeoutException, is IOException -> true
            is HttpFailure -> t.status == 408 || t.status == 429 || t.status in 500..599
            is UnusableAnswer -> true
            else -> false
        }
    }

    /**
     * One chat completion. [onDelta] receives text pieces as they arrive so the
     * UI can show progress; [isCancelled] is polled between chunks and before
     * every retry, which is what makes ⏹ stop a running turn.
     */
    fun chat(
        messages: JSONArray,
        tools: JSONArray?,
        isCancelled: () -> Boolean = { false },
        onDelta: ((String) -> Unit)? = null,
    ): Response {
        var attempt = 0
        var stream = true
        var backoff = RETRY_BACKOFF_MS
        while (true) {
            if (isCancelled()) throw LlmException(CANCELLED)
            attempt++
            try {
                return request(messages, tools, stream, isCancelled, if (stream) onDelta else null)
            } catch (t: Throwable) {
                if (isCancelled()) throw LlmException(CANCELLED)
                // The server ignored `stream` (or answered with something odd):
                // spend the same attempt on a plain, non-streamed request.
                if (t is UnusableAnswer && stream) {
                    stream = false
                    attempt--
                    continue
                }
                if (attempt >= MAX_ATTEMPTS || !isRetryable(t)) throw LlmException(describe(t))
                nap(backoff, isCancelled)
                backoff *= 2
            }
        }
    }

    // ---------------------------------------------------------------- request

    private fun request(
        messages: JSONArray,
        tools: JSONArray?,
        stream: Boolean,
        isCancelled: () -> Boolean,
        onDelta: ((String) -> Unit)?,
    ): Response {
        val body = JSONObject().apply {
            put("model", config.model)
            put("messages", messages)
            put("temperature", 0.2)
            if (tools != null && tools.length() > 0) {
                put("tools", tools)
                put("tool_choice", "auto")
            }
            if (stream) put("stream", true)
        }

        val conn = (URL(config.endpoint).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            connectTimeout = CONNECT_TIMEOUT_MS
            readTimeout = READ_TIMEOUT_MS
            doOutput = true
            setRequestProperty("Content-Type", "application/json")
            setRequestProperty("Accept", if (stream) "text/event-stream, application/json" else "application/json")
            // No Authorization header without a key: local servers reject
            // stray headers far less often than cloud ones reject bad keys.
            if (config.apiKey.isNotBlank()) {
                setRequestProperty("Authorization", "Bearer ${config.apiKey}")
            }
        }
        val watchdog = Watchdog(conn)
        watchdog.start()
        try {
            conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
            val status = conn.responseCode
            if (status !in 200..299) {
                throw HttpFailure(status, readText(conn.errorStream))
            }
            watchdog.beat()
            return readAnswer(conn, watchdog, isCancelled, onDelta)
        } catch (e: IOException) {
            if (watchdog.fired) throw SocketTimeoutException("нет данных от сервера модели")
            throw e
        } finally {
            watchdog.stop()
            conn.disconnect()
        }
    }

    /**
     * Reads the answer line by line: SSE chunks when the server streams them,
     * otherwise the whole body as one JSON document.
     */
    private fun readAnswer(
        conn: HttpURLConnection,
        watchdog: Watchdog,
        isCancelled: () -> Boolean,
        onDelta: ((String) -> Unit)?,
    ): Response {
        val reader = conn.inputStream.bufferedReader(Charsets.UTF_8)
        val stream = Stream(onDelta)
        val plain = StringBuilder()
        var sawChunk = false
        while (true) {
            if (isCancelled()) throw LlmException(CANCELLED)
            val line = reader.readLine() ?: break
            if (line.isBlank()) continue
            if (line.startsWith(SSE_DATA)) {
                sawChunk = true
                val payload = line.removePrefix(SSE_DATA).trim()
                if (payload == SSE_DONE) break
                stream.feed(payload)
            } else if (!sawChunk) {
                // Not a stream: accumulate the plain JSON body.
                plain.append(line)
            }
            watchdog.beat()
        }
        if (sawChunk) return stream.result()
        val body = plain.toString().trim()
        if (body.isEmpty()) throw UnusableAnswer("сервер вернул пустой ответ")
        val json = try {
            JSONObject(body)
        } catch (t: Throwable) {
            throw UnusableAnswer("ожидался JSON, получено: ${body.take(120)}")
        }
        json.optJSONObject("error")?.let { err ->
            throw LlmException("сервер модели вернул ошибку: ${err.optString("message").ifEmpty { body.take(200) }}")
        }
        val choices = json.optJSONArray("choices")
        if (choices == null || choices.length() == 0) throw UnusableAnswer("в ответе нет choices: ${body.take(200)}")
        return parseMessage(choices.getJSONObject(0).getJSONObject("message"))
    }

    private fun readText(stream: java.io.InputStream?): String =
        stream?.bufferedReader(Charsets.UTF_8)?.use { it.readText() } ?: ""

    /** Interruptible backoff between retries. */
    private fun nap(ms: Long, isCancelled: () -> Boolean) {
        val deadline = System.currentTimeMillis() + ms
        while (System.currentTimeMillis() < deadline) {
            if (isCancelled()) throw LlmException(CANCELLED)
            try {
                Thread.sleep(250)
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                throw LlmException(CANCELLED)
            }
        }
    }

    /**
     * Closes a connection that stopped delivering bytes. HttpURLConnection's
     * read timeout is a per-read value, so a server that stops mid-answer would
     * otherwise hold the turn for the full deadline.
     */
    private class Watchdog(private val conn: HttpURLConnection) {
        private val lastData = AtomicLong(System.currentTimeMillis())
        private val gotData = AtomicBoolean(false)

        /** True when the watchdog, not the server, ended the connection. */
        @Volatile
        var fired: Boolean = false

        @Volatile
        private var stopped: Boolean = false

        fun start() {
            Thread({
                while (!stopped) {
                    Thread.sleep(2_000)
                    if (stopped) return@Thread
                    val idle = System.currentTimeMillis() - lastData.get()
                    val limit = if (gotData.get()) STALL_TIMEOUT_MS else FIRST_TOKEN_TIMEOUT_MS
                    if (idle > limit) {
                        fired = true
                        runCatching { conn.disconnect() }
                        return@Thread
                    }
                }
            }, "llm-watchdog").apply {
                isDaemon = true
                start()
            }
        }

        /** Called for every piece of data that arrived. */
        fun beat() {
            lastData.set(System.currentTimeMillis())
            gotData.set(true)
        }

        fun stop() {
            stopped = true
        }
    }
}

